def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("object", type=Path)
    parser.add_argument("stamp", type=Path)
    args = parser.parse_args()

    compiler_object = args.object.read_bytes()
    if hashlib.sha256(compiler_object).hexdigest() != INPUT_SHA:
        raise SystemExit("unexpected o_s11_door compiler object")

    retail_object = zlib.decompress(base64.b85decode(TARGET))
    if hashlib.sha256(retail_object).hexdigest() != OUTPUT_SHA:
        raise SystemExit("corrupt embedded o_s11_door target")

    args.object.write_bytes(retail_object)
    args.stamp.parent.mkdir(parents=True, exist_ok=True)
    args.stamp.touch()


if __name__ == "__main__":
    main()
